    /**
     * Tests creating a new Beneficiary.
     *
     * @return    Beneficiary
     */
    public Beneficiary testCreate() throws Throwable {
    Beneficiary entity = null;

    LOGGER.info( "BeneficiaryTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Beneficiary");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Beneficiary" );

    try {
        entity = service.createBeneficiary( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getBeneficiaryId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Beneficiary with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

