    /**
     * Tests getting all Beneficiarys.
     *
     * @return    Collection
     */
    public List<Beneficiary> testGetAll() throws Throwable {
    LOGGER.info( "BeneficiaryTest:testGetAll() - Retrieving Collection of Beneficiarys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Beneficiary : " );
    List<Beneficiary> collection  = null;

    try {
        // call the static get method on the BeneficiaryService
        collection = service.getAllBeneficiary();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Beneficiary currEntity  = null;
            Iterator<Beneficiary> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBeneficiaryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

